"use client";

import Link from "next/link";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";
import { Crown } from "lucide-react";
import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type FocusEvent,
} from "react";
import { createPortal } from "react-dom";

export type PremiumLockProps = {
  feature: string;
  upgradeFeature?: import("./premium-upgrade-dialog").UpgradeFeature;
  variant?: "icon" | "notice";
  title?: string;
  description?: string;
  showUpgrade?: boolean;
  showCheckoutNote?: boolean;
};

export function PremiumLock({
  feature,
  upgradeFeature,
  variant = "icon",
  title = "Premium required",
  description = feature,
  showUpgrade = true,
  showCheckoutNote = true,
}: PremiumLockProps) {
  const upgrade = usePremiumUpgrade();
  const id = useId();
  const button = useRef<HTMLButtonElement>(null);
  const bubble = useRef<HTMLDivElement>(null);
  const link = useRef<HTMLAnchorElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const pointerWasOpen = useRef<boolean | null>(null);
  const [open, setOpen] = useState(false);
  const [position, setPosition] = useState<{ left: number; top: number }>();

  const cancelClose = () => clearTimeout(timer.current);
  const close = useCallback(() => {
    clearTimeout(timer.current);
    setOpen(false);
  }, []);
  const show = () => {
    cancelClose();
    setOpen(true);
  };
  const leave = () => {
    cancelClose();
    timer.current = setTimeout(() => setOpen(false), 120);
  };
  const blur = (event: FocusEvent<HTMLElement>) => {
    if (
      button.current?.contains(event.relatedTarget) ||
      bubble.current?.contains(event.relatedTarget)
    )
      return;
    close();
  };

  useEffect(() => () => clearTimeout(timer.current), []);

  useLayoutEffect(() => {
    if (!open) return;
    const reposition = () => {
      if (!button.current || !bubble.current) return;
      const rect = button.current.getBoundingClientRect();
      const tip = bubble.current.getBoundingClientRect();
      const below = window.innerHeight - rect.bottom - 10;
      const above = rect.top - 10;
      const flip = below < tip.height + 8 && above > below;
      setPosition({
        left: Math.max(
          10,
          Math.min(
            rect.left + rect.width / 2 - tip.width / 2,
            window.innerWidth - tip.width - 10,
          ),
        ),
        top: Math.max(
          10,
          Math.min(
            flip ? rect.top - tip.height - 8 : rect.bottom + 8,
            window.innerHeight - tip.height - 10,
          ),
        ),
      });
    };
    reposition();
    const observer = new ResizeObserver(reposition);
    if (bubble.current) observer.observe(bubble.current);
    window.addEventListener("resize", reposition);
    window.addEventListener("scroll", reposition, true);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", reposition);
      window.removeEventListener("scroll", reposition, true);
    };
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const outside = (event: PointerEvent) => {
      if (
        event.target instanceof Node &&
        !button.current?.contains(event.target) &&
        !bubble.current?.contains(event.target)
      )
        close();
    };
    const escape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      if (bubble.current?.contains(document.activeElement))
        button.current?.focus();
      close();
    };
    document.addEventListener("pointerdown", outside);
    document.addEventListener("keydown", escape);
    return () => {
      document.removeEventListener("pointerdown", outside);
      document.removeEventListener("keydown", escape);
    };
  }, [open, close]);

  return (
    <>
      <button
        ref={button}
        type="button"
        className={
          variant === "notice"
            ? `workspace-mono:rounded-[var(--appearance-control-radius)] flex items-center gap-2.5 w-full py-2 px-3.5 rounded-[12px] [border:1px_solid_var(--premium-notice-border)] [background:var(--premium-notice-background)] text-[var(--premium-notice-text)] text-[12.5px] text-left cursor-pointer focus-visible:[outline:2px_solid_var(--accent)] focus-visible:[outline-offset:2px]`
            : `workspace-mono:rounded-[var(--appearance-control-radius)] inline-flex shrink-0 items-center justify-center w-7 h-7 p-0 rounded-full [border:1px_solid_var(--premium-notice-border)] [background:var(--premium-notice-background)] text-[var(--premium-notice-text)] cursor-pointer focus-visible:[outline:2px_solid_var(--accent)] focus-visible:[outline-offset:2px]`
        }
        aria-label={`${title}: ${feature}`}
        aria-describedby={open ? id : undefined}
        aria-expanded={open}
        onMouseEnter={show}
        onMouseLeave={leave}
        onFocus={show}
        onBlur={blur}
        onPointerDown={() => {
          pointerWasOpen.current = open;
        }}
        onPointerCancel={() => {
          pointerWasOpen.current = null;
        }}
        onClick={() => {
          cancelClose();
          if (showUpgrade) {
            close();
            upgrade({ feature: upgradeFeature, trigger: button.current });
          } else setOpen(!(pointerWasOpen.current ?? open));
          pointerWasOpen.current = null;
        }}
        onKeyDown=[REDACTED_SECRET]
          if (event.key === "Tab" && !event.shiftKey && open && link.current) {
            event.preventDefault();
            link.current.focus();
          }
        }}
      >
        <Crown size={16} className="premium-icon" aria-hidden="true" />
        {variant === "notice" && <span>{feature} · Premium required</span>}
      </button>
      {open &&
        createPortal(
          <div
            ref={bubble}
            id={id}
            role="tooltip"
            className={`workspace-mono:rounded-[var(--appearance-radius)] workspace-mono:shadow-[0_4px_16px_var(--color-premium-lock-box-shadow-2)] fixed z-[1000] box-border w-max max-w-[min(300px,_calc(100vw_-_20px))] max-h-[calc(100dvh_-_20px)] overflow-y-auto wrap-anywhere rounded-[14px] [border:1px_solid_var(--border)] [background:var(--card)] text-foreground py-3 px-3.5 shadow-[0_14px_40px_var(--color-premium-lock-box-shadow-1)] text-[13px] leading-normal`}
            style={{
              left: position?.left ?? 10,
              top: position?.top ?? 10,
              visibility: position ? "visible" : "hidden",
            }}
            onMouseEnter={cancelClose}
            onMouseLeave={leave}
            onFocus={cancelClose}
            onBlur={blur}
            onKeyDown=[REDACTED_SECRET]
              if (event.key === "Tab" && event.shiftKey) {
                event.preventDefault();
                button.current?.focus();
              }
            }}
          >
            <div className="space-y-1">
              <p className="font-semibold">{title}</p>
              <p className="text-body">{description}</p>
              {showUpgrade && (
                <Link
                  ref={link}
                  href="/usage"
                  className="relative isolate inline-block overflow-hidden align-middle text-link underline"
                >
                  View Premium plan
                </Link>
              )}
              {showCheckoutNote && (
                <p className="text-body">
                  Checkout is available in Usage when configured.
                </p>
              )}
            </div>
          </div>,
          document.getElementById("main-content") ?? document.body,
        )}
    </>
  );
}
